import math, logging
from . import bus, tmc, tmc2130
Registers = {
  'DRVCONF': 14,  'SGCSCONF': 12,  'SMARTEN': 10,
  'CHOPCONF': 8,  'DRVCTRL': 0}
ReadRegisters = [
 "READRSP@RDSEL0", "READRSP@RDSEL1", "READRSP@RDSEL2"]
Fields = {}
Fields["DRVCTRL"] = {'mres':15, 
 'dedge':256, 
 'intpol':512}
Fields["CHOPCONF"] = {
  'toff': 15,
  'hstrt': 112,
  'hend': 1920,
  'hdec': 6144,
  'rndtf': 8192,
  'chm': 16384,
  'tbl': 98304}
Fields["SMARTEN"] = {
  'semin': 15,
  'seup': 96,
  'semax': 3840,
  'sedn': 24576,
  'seimin': 32768}
Fields["SGCSCONF"] = {'cs':31, 
 'sgt':32512, 
 'sfilt':65536}
Fields["DRVCONF"] = {
  'rdsel': 48,
  'vsense': 64,
  'sdoff': 128,
  'ts2g': 768,
  'diss2g': 1024,
  'slpl': 12288,
  'slph': 49152,
  'tst': 65536}
Fields["READRSP@RDSEL0"] = {
  'stallguard': 16,
  'ot': 32,
  'otpw': 64,
  's2ga': 128,
  's2gb': 256,
  'ola': 512,
  'olb': 1024,
  'stst': 2048,
  'mstep': 16760832}
Fields["READRSP@RDSEL1"] = {
  'stallguard': 16,
  'ot': 32,
  'otpw': 64,
  's2ga': 128,
  's2gb': 256,
  'ola': 512,
  'olb': 1024,
  'stst': 2048,
  'sg_result': 16760832}
Fields["READRSP@RDSEL2"] = {
  'stallguard': 16,
  'ot': 32,
  'otpw': 64,
  's2ga': 128,
  's2gb': 256,
  'ola': 512,
  'olb': 1024,
  'stst': 2048,
  'se': 507904,
  'sg_result@rdsel2': 16252928}
SignedFields = [
 "sgt"]
FieldFormatters = dict(tmc2130.FieldFormatters)
FieldFormatters.update({'chm':lambda v: "1(constant toff)" if v else "0(spreadCycle)", 
 'vsense':lambda v: "1(165mV)" if v else "0(305mV)", 
 'sdoff':lambda v: "1(Step/Dir disabled!)" if v else "", 
 'diss2g':lambda v: "1(Short to GND disabled!)" if v else "", 
 'se':lambda v: ("%d" % v) if v else "0(Reset?)"})
MAX_CURRENT = 2.4

class TMC2660CurrentHelper:

    def __init__(self, config, mcu_tmc):
        self.printer = config.get_printer()
        self.name = config.get_name().split()[-1]
        self.mcu_tmc = mcu_tmc
        self.fields = mcu_tmc.get_fields()
        self.current = config.getfloat("run_current", minval=0.1, maxval=MAX_CURRENT)
        self.sense_resistor = config.getfloat("sense_resistor")
        vsense, cs = self._calc_current(self.current)
        self.fields.set_field("cs", cs)
        self.fields.set_field("vsense", vsense)
        self.idle_current_percentage = config.getint("idle_current_percent",
          default=100, minval=0, maxval=100)
        if self.idle_current_percentage < 100:
            self.printer.register_event_handler("idle_timeout:printing", self._handle_printing)
            self.printer.register_event_handler("idle_timeout:ready", self._handle_ready)

    def _calc_current_bits(self, current, vsense):
        vref = 0.165 if vsense else 0.31
        sr = self.sense_resistor
        cs = int(32.0 * sr * current * math.sqrt(2.0) / vref + 0.5) - 1
        return max(0, min(31, cs))

    def _calc_current_from_bits(self, cs, vsense):
        vref = 0.165 if vsense else 0.31
        return (cs + 1) * vref / (32.0 * self.sense_resistor * math.sqrt(2.0))

    def _calc_current(self, run_current):
        vsense = True
        irun = self._calc_current_bits(run_current, True)
        if irun == 31:
            cur = self._calc_current_from_bits(irun, True)
            if cur < run_current:
                irun2 = self._calc_current_bits(run_current, False)
                cur2 = self._calc_current_from_bits(irun2, False)
                if abs(run_current - cur2) < abs(run_current - cur):
                    vsense = False
                    irun = irun2
            return (
             vsense, irun)

    def _handle_printing(self, print_time):
        print_time -= 0.1
        self.printer.get_reactor().register_callback(lambda ev: self._update_current(self.current, print_time))

    def _handle_ready(self, print_time):
        current = self.current * float(self.idle_current_percentage) / 100.0
        self.printer.get_reactor().register_callback(lambda ev: self._update_current(current, print_time))

    def _update_current(self, current, print_time):
        (vsense, cs) = self._calc_current(current)
        val = self.fields.set_field("cs", cs)
        self.mcu_tmc.set_register("SGCSCONF", val, print_time)
        if vsense != self.fields.get_field("vsense"):
            val = self.fields.set_field("vsense", vsense)
            self.mcu_tmc.set_register("DRVCONF", val, print_time)

    def get_current(self):
        return (
         self.current, None, None, MAX_CURRENT)

    def set_current(self, run_current, hold_current, print_time):
        self.current = run_current
        self._update_current(run_current, print_time)


class MCU_TMC2660_SPI:

    def __init__(self, config, name_to_reg, fields):
        self.printer = config.get_printer()
        self.mutex = self.printer.get_reactor().mutex()
        self.spi = bus.MCU_SPI_from_config(config, 0, default_speed=4000000)
        self.name_to_reg = name_to_reg
        self.fields = fields

    def get_fields(self):
        return self.fields

    def get_register(self, reg_name):
        new_rdsel = ReadRegisters.index(reg_name)
        reg = self.name_to_reg["DRVCONF"]
        if self.printer.get_start_args().get("debugoutput") is not None:
            return 0
        with self.mutex:
            old_rdsel = self.fields.get_field("rdsel")
            val = self.fields.set_field("rdsel", new_rdsel)
            msg = [(val >> 16 | reg) & 255, val >> 8 & 255, val & 255]
            if new_rdsel != old_rdsel:
                self.spi.spi_send(msg)
            params = self.spi.spi_transfer(msg)
        pr = bytearray(params["response"])
        return pr[0] << 16 | pr[1] << 8 | pr[2]

    def set_register(self, reg_name, val, print_time=None):
        minclock = 0
        if print_time is not None:
            minclock = self.spi.get_mcu().print_time_to_clock(print_time)
        reg = self.name_to_reg[reg_name]
        msg = [(val >> 16 | reg) & 255, val >> 8 & 255, val & 255]
        with self.mutex:
            self.spi.spi_send(msg, minclock)

    def get_tmc_frequency(self):
        pass


class TMC2660:

    def __init__(self, config):
        self.fields = tmc.FieldHelper(Fields, SignedFields, FieldFormatters)
        self.fields.set_field("sdoff", 0)
        self.mcu_tmc = MCU_TMC2660_SPI(config, Registers, self.fields)
        current_helper = TMC2660CurrentHelper(config, self.mcu_tmc)
        cmdhelper = tmc.TMCCommandHelper(config, self.mcu_tmc, current_helper)
        cmdhelper.setup_register_dump(ReadRegisters)
        self.get_phase_offset = cmdhelper.get_phase_offset
        self.get_status = cmdhelper.get_status
        set_config_field = self.fields.set_config_field
        set_config_field(config, "tbl", 2)
        set_config_field(config, "rndtf", 0)
        set_config_field(config, "hdec", 0)
        set_config_field(config, "chm", 0)
        set_config_field(config, "hend", 3)
        set_config_field(config, "hstrt", 3)
        set_config_field(config, "toff", 4)
        if not self.fields.get_field("chm"):
            if self.fields.get_field("hstrt") + self.fields.get_field("hend") > 15:
                raise config.error("driver_HEND + driver_HSTRT must be <= 15")
        set_config_field(config, "seimin", 0)
        set_config_field(config, "sedn", 0)
        set_config_field(config, "semax", 0)
        set_config_field(config, "seup", 0)
        set_config_field(config, "semin", 0)
        set_config_field(config, "sfilt", 0)
        set_config_field(config, "sgt", 0)
        set_config_field(config, "slph", 0)
        set_config_field(config, "slpl", 0)
        set_config_field(config, "diss2g", 0)
        set_config_field(config, "ts2g", 3)


def load_config_prefix(config):
    return TMC2660(config)

